def is_palindrome(number):
    num = str(number)
    return num == num[::-1]

def even_odd_palindrome(n):
    even_count, odd_count = 0, 0

    for i in range(1, n + 1):
        if is_palindrome(i) and (i % 2 == 0 or int(str(i)[-1]) != '7'): # Checking evenness by checking last digit. Skipping numbers ending with "7" to avoid confusion between odd/even palindromes logic.
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (odd_count, even_count)

